import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Twelve-factor design, with explicit storage boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/twelve-factor.md","filePath":"engineering/twelve-factor.md","lastUpdated":1794376220000}'),i={name:"engineering/twelve-factor.md"};function n(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="twelve-factor-design-with-explicit-storage-boundaries" tabindex="-1">Twelve-factor design, with explicit storage boundaries <a class="header-anchor" href="#twelve-factor-design-with-explicit-storage-boundaries" aria-label="Permalink to &quot;Twelve-factor design, with explicit storage boundaries&quot;">​</a></h1><p>The <a href="https://12factor.net/" target="_blank" rel="noreferrer">Twelve-Factor App</a> describes deployable services. We apply it to the hosted API and workers without pretending that a portable research database is stateless. These are <strong>design requirements, not a compliance certificate</strong>. Runtime gates remain pending until the application exists and is tested.</p><h2 id="two-profiles-one-codebase" tabindex="-1">Two profiles, one codebase <a class="header-anchor" href="#two-profiles-one-codebase" aria-label="Permalink to &quot;Two profiles, one codebase&quot;">​</a></h2><p><strong>Hosted:</strong> the API and compute workers are replaceable processes. A private Rust store process owns SQLite and durable artifacts as an attached backing service. Sessions, runs, leases, review decisions and replay cursors survive replacing an API process. The browser has one public origin; the store is not publicly exposed.</p><p><strong>Local appliance:</strong> the same domain/storage modules may run together with an explicitly selected library directory. This stateful convenience is a documented exception to strict process disposability and horizontal scale. It must still pass backup, recovery, configuration and provenance tests.</p><p>A volume is not a magic statelessness switch. The hosted store remains stateful and single-writer per writable library; it needs its own backup/restore contract. We do not mount a live SQLite WAL database over a network filesystem. SQLite documents that WAL processes must operate on the same host. <a href="https://sqlite.org/wal.html" target="_blank" rel="noreferrer">SQLite WAL</a>.</p><h2 id="verification-matrix" tabindex="-1">Verification matrix <a class="header-anchor" href="#verification-matrix" aria-label="Permalink to &quot;Verification matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Factor and project decision</th><th>Falsifiable acceptance evidence</th></tr></thead><tbody><tr><td>TF-01</td><td><a href="https://12factor.net/codebase" target="_blank" rel="noreferrer">Codebase</a>: one application workspace, many deployments; donor history recorded, not separate environment forks</td><td>QA and production identify the same source revision and selected artifact; no production-only source patches</td></tr><tr><td>TF-02</td><td><a href="https://12factor.net/dependencies" target="_blank" rel="noreferrer">Dependencies</a>: commit lockfiles; pin toolchains, base images, OS tools and model/tokenizer manifests</td><td>Clean checkout builds using declared inputs; removing an undeclared tool causes an explicit readiness failure, not hidden fallback</td></tr><tr><td>TF-03</td><td><a href="https://12factor.net/config" target="_blank" rel="noreferrer">Configuration</a>: deployment values supplied independently of code; strict typed parsing; secrets server-only</td><td>Same built artifact accepts different endpoint/limits configuration; malformed supplied values fail startup; secret scan/log tests show no disclosure</td></tr><tr><td>TF-04</td><td><a href="https://12factor.net/backing-services" target="_blank" rel="noreferrer">Backing services</a>: hosted API attaches to a private state service and model endpoints through contracts</td><td>Replace the store endpoint or inference provider configuration without recompiling the API; incompatible contracts are rejected</td></tr><tr><td>TF-05</td><td><a href="https://12factor.net/build-release-run" target="_blank" rel="noreferrer">Build, release, run</a>: immutable artifacts, configuration-bound release manifest, no build at startup</td><td>Promote the tested digest without rebuilding; startup runs with no compiler or package registry access; retain schema/library compatibility evidence</td></tr><tr><td>TF-06</td><td><a href="https://12factor.net/processes" target="_blank" rel="noreferrer">Processes</a>: hosted API/workers keep no sole durable truth in memory or writable process files</td><td>Replace an API with an empty ephemeral filesystem; history, ownership and committed replay remain correct; local embedded-store exception is declared</td></tr><tr><td>TF-07</td><td><a href="https://12factor.net/port-binding" target="_blank" rel="noreferrer">Port binding</a>: the server binds a configured address and port; proxy is external</td><td>Run behind a different approved proxy without changing application source; health/readiness and actual HTTPS streams pass</td></tr><tr><td>TF-08</td><td><a href="https://12factor.net/concurrency" target="_blank" rel="noreferrer">Concurrency</a>: scale explicit process roles and bounded worker slots, not uncontrolled threads</td><td>Two workers race for one task; one acceptance succeeds; stale epoch fails; queue/memory limits hold; no claim of horizontally replicated SQLite writers</td></tr><tr><td>TF-09</td><td><a href="https://12factor.net/disposability" target="_blank" rel="noreferrer">Disposability</a>: fast readiness, graceful shutdown and crash recovery</td><td>SIGTERM stops admission and drains within a configured grace; SIGKILL does not duplicate accepted work; interrupted runs and lease recovery remain visible</td></tr><tr><td>TF-10</td><td><a href="https://12factor.net/dev-prod-parity" target="_blank" rel="noreferrer">Development/production parity</a>: same storage engine, protocol and release path; platform capabilities vary explicitly</td><td>Linux QA runs the production image and schema; Mac/Swift workers pass common contract fixtures; mock inference is not presented as model-quality validation</td></tr><tr><td>TF-11</td><td><a href="https://12factor.net/logs" target="_blank" rel="noreferrer">Logs</a>: structured event output to stdout/stderr, aggregated by the environment</td><td>No application-managed production log rotation; logs carry request/run IDs but omit credentials, raw sensitive inputs and provider payloads</td></tr><tr><td>TF-12</td><td><a href="https://12factor.net/admin-processes" target="_blank" rel="noreferrer">Admin processes</a>: one-off migration, import, verification and export use the same release and policy</td><td>Run a scoped admin operation with target guard and least privilege; retain an audit receipt; reject incompatible schema or production target in destructive tests</td></tr></tbody></table><h2 id="configuration-contract" tabindex="-1">Configuration contract <a class="header-anchor" href="#configuration-contract" aria-label="Permalink to &quot;Configuration contract&quot;">​</a></h2><p>Proposed runtime variables are granular, validated settings, not a single opaque <code>production</code> switch:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning and boundary</th></tr></thead><tbody><tr><td><code>LAB_BIND_ADDR</code>, <code>LAB_PORT</code></td><td>HTTP bind location; local defaults may be loopback, container deployment explicitly binds an approved interface</td></tr><tr><td><code>LAB_STORE_URL</code></td><td>Private store endpoint for hosted API/workers</td></tr><tr><td><code>LAB_LIBRARY_PATH</code></td><td>Store/local-authoring process only; never a browser-selected filesystem path</td></tr><tr><td><code>LAB_MODEL_MODE</code></td><td>Explicit <code>mock</code>, <code>local</code> or <code>remote</code>; absence is not silent permission to call a provider</td></tr><tr><td><code>LAB_MODEL_ENDPOINT</code></td><td>Operator-controlled, allowlisted model service</td></tr><tr><td><code>LAB_MAX_CONCURRENT_RUNS</code>, <code>LAB_MAX_OUTPUT_BYTES</code></td><td>Positive bounded limits; parsed on startup</td></tr><tr><td><code>LAB_SHUTDOWN_GRACE_SECONDS</code></td><td>Grace budget coordinated with the process supervisor</td></tr></tbody></table><p>Secrets use the deployment&#39;s credential injection mechanism and are never committed, returned in public configuration or printed. A variable carrying a secret-file reference is a deliberate injection choice, not permission to put its contents into a release manifest.</p><p>The Svelte frontend should use relative <code>/api</code> paths and a sanitized runtime configuration endpoint when needed. Environment-specific URLs baked into JavaScript at build time would prevent promoting exactly the same frontend artifact. Public runtime configuration is an allowlist, not a dump of the process environment.</p><h2 id="state-and-release-rules" tabindex="-1">State and release rules <a class="header-anchor" href="#state-and-release-rules" aria-label="Permalink to &quot;State and release rules&quot;">​</a></h2><p>The canonical store transaction owns graph changes and their events. The hosted conversation store is operational state, separate from the immutable published research snapshot. No cross-database atomic transaction is assumed: each answer pins an already published library revision and records that reference durably in its own run transaction.</p><p>A release manifest records source revision, application artifact digest, schema compatibility range, selected library revision, embedding-space identities and enabled worker/model versions. Configuration fingerprints exclude secret values. A schema-changing release may require a forward repair or a restore; switching an image tag alone is not a safe rollback plan.</p><p>Operational logs and the evidence audit ledger are different. Stdout logs support diagnosis; the audit ledger is durable, access-controlled application data and must participate in the relevant transaction and retention policy.</p><h2 id="explicit-exceptions-and-nonclaims" tabindex="-1">Explicit exceptions and nonclaims <a class="header-anchor" href="#explicit-exceptions-and-nonclaims" aria-label="Permalink to &quot;Explicit exceptions and nonclaims&quot;">​</a></h2><p>The local embedded store does not meet strict stateless-process scaling. The hosted private store is a stateful backing resource, not an API replica. CUDA and Apple implementations need compatible contracts but need not produce bit-identical floating-point output. Multi-architecture images require separately built and tested artifacts; an OCI index alone does not prove parity.</p><p>Do not claim twelve-factor compliance because the project uses Docker, Rust or environment variables. Claim each tested property separately. The <a href="./clean-build">clean-build plan</a>, <a href="./examples">examples</a> and <a href="./../project/roadmap">roadmap</a> turn these gates into work.</p>',20)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
